// Registration expiry for every watched domain, for the report's "coming up"
// section. The domain list comes from the Domains tab of the Domain Guard sheet.
const DOMAINS = [...new Set($input.all().map(i => String(i.json.Domain ?? '').trim().toLowerCase()).filter(Boolean))];
const WINDOW_DAYS = 60;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

// Registries rate-limit bursts, so retry 429s and server errors with a pause.
const lookup = async (domain) => {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://rdap.org/domain/' + domain, headers: { Accept: 'application/rdap+json' }, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000, json: true });
      if (res.statusCode !== 429 && res.statusCode < 500) return res;
    } catch (e) {
      if (attempt === 3) throw e;
    }
    await sleep(3000 * attempt);
  }
  return { statusCode: 429 };
};

const expiring = [];
const skipped = [];
for (const domain of DOMAINS) {
  try {
    const res = await lookup(domain);
    if (res.statusCode === 404) {
      expiring.push({ domain, expires: 'not registered', days: -1 });
    } else if (res.statusCode === 200) {
      const j = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
      const expires = (j.events || []).find(e => e.eventAction === 'expiration')?.eventDate ?? null;
      const days = expires ? Math.floor((new Date(expires) - new Date()) / 86400000) : null;
      if (days !== null && days <= WINDOW_DAYS) expiring.push({ domain, expires: expires.slice(0, 10), days });
    } else {
      skipped.push(domain);
    }
  } catch (e) {
    skipped.push(domain);
  }
  await sleep(1000);
}
expiring.sort((a, b) => a.days - b.days);
return [{ json: { expiring, skipped, windowDays: WINDOW_DAYS } }];

// Weekly summary email: incidents, approvals and upcoming registration expiries.
const DAY = 86400000;
const now = new Date();
const since = new Date(now - 7 * DAY);
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inWeek = (v) => { const d = new Date(v); return !isNaN(d) && d >= since; };
const day = (v) => String(v || '').slice(0, 10);
const duration = (m) => (m === null || isNaN(m)) ? 'n/a' : m < 120 ? m + ' min' : (m / 60).toFixed(1) + ' h';

const incidents = $('Read incidents').all().map(i => i.json).filter(r => r['Incident ID']);
const approvals = $('Read approvals').all().map(i => i.json).filter(r => r['Approval ID']);
const { expiring, skipped, windowDays } = $input.first().json;

const opened = incidents.filter(r => inWeek(r['Opened At']));
const resolved = incidents.filter(r => r['Status'] === 'Resolved' && inWeek(r['Resolved At']));
const stillOpen = incidents.filter(r => r['Status'] !== 'Resolved');
const minutes = resolved.map(r => Number(r['Minutes Open'])).filter(n => !isNaN(n)).sort((a, b) => a - b);
const median = minutes.length ? minutes[Math.floor(minutes.length / 2)] : null;
const perDomain = {};
opened.forEach(r => { perDomain[r['Domain']] = (perDomain[r['Domain']] || 0) + 1; });
const busiest = Object.entries(perDomain).filter(([, n]) => n > 1).sort((a, b) => b[1] - a[1]).slice(0, 5);
const requested = approvals.filter(r => inWeek(r['Requested At']));
const decided = approvals.filter(r => r['Status'] !== 'Pending' && inWeek(r['Decided At']));
const pending = approvals.filter(r => r['Status'] === 'Pending');

const cell = 'padding:4px 12px 4px 0;vertical-align:top;text-align:left';
const table = (headers, rows) => rows.length
  ? '<table style="border-collapse:collapse;font-size:14px"><tr>' + headers.map(h => '<th style="' + cell + ';border-bottom:1px solid #d0d7de">' + esc(h) + '</th>').join('') + '</tr>'
    + rows.map(r => '<tr>' + r.map(c => '<td style="' + cell + '">' + esc(c) + '</td>').join('') + '</tr>').join('') + '</table>'
  : '<p style="color:#57606a">None.</p>';
const h3 = (t) => '<h3 style="margin:24px 0 8px">' + esc(t) + '</h3>';

const html = '<div style="font-family:-apple-system,Segoe UI,sans-serif;color:#1f2328;max-width:680px">'
  + '<h2 style="margin:0 0 4px">Domain Guard weekly report</h2>'
  + '<p style="color:#57606a;margin:0 0 16px">' + day(since.toISOString()) + ' to ' + day(now.toISOString()) + '</p>'
  + '<p><b>' + opened.length + '</b> incidents opened, <b>' + resolved.length + '</b> resolved, <b>' + stillOpen.length + '</b> still open. Median time to resolve: <b>' + duration(median) + '</b>.<br>'
  + '<b>' + requested.length + '</b> approvals requested, <b>' + decided.filter(r => r['Status'] === 'Approved').length + '</b> approved, <b>' + decided.filter(r => r['Status'] === 'Rejected').length + '</b> rejected, <b>' + pending.length + '</b> waiting on you.</p>'
  + h3('Open incidents') + table(['Incident', 'Domain', 'Status', 'Opened', 'Updates'], stillOpen.map(r => [r['Incident ID'], r['Domain'], r['Status'], day(r['Opened At']), r['Updates']]))
  + h3('Resolved this week') + table(['Incident', 'Domain', 'Events', 'Time open'], resolved.map(r => [r['Incident ID'], r['Domain'], r['Event Types'], duration(Number(r['Minutes Open']))]))
  + (busiest.length ? h3('Domains with repeat incidents') + table(['Domain', 'Incidents this week'], busiest) : '')
  + h3('Approvals waiting on you') + table(['Request', 'Domain', 'Requested'], pending.map(r => [r['Approval ID'], r['Domain'], day(r['Requested At'])]))
  + h3('Registrations expiring within ' + windowDays + ' days') + table(['Domain', 'Expires', 'Days left'], expiring.map(e => [e.domain, e.expires, e.days < 0 ? '' : e.days]))
  + (skipped.length ? '<p style="color:#57606a">Registry lookup failed for: ' + esc(skipped.join(', ')) + '.</p>' : '')
  + '</div>';

return [{ json: {
  subject: 'Domain Guard weekly report: ' + opened.length + ' new, ' + stillOpen.length + ' open, ' + pending.length + ' awaiting approval',
  html,
} }];
